const user = $json;
const dias = user.dias_inativo || 0;
const nome = user.nome || 'amigo(a)';
const objetivo = user.objetivo || 'manter forma';
const ultimoTreino = user.ultimo_treino || 'nenhum recente';
const treinosMes = user.treinos_mes || 0;

// Seleciona tom baseado no tempo de inatividade
let tom;
if (dias <= 3) {
  tom = 'lembrete leve e amigável';
} else if (dias <= 7) {
  tom = 'motivacional com senso de urgência gentil';
} else {
  tom = 'empático e acolhedor, sem julgamento, incentivando retomada';
}

const prompt = `Gere uma mensagem de reengajamento para:
- Nome: ${nome}
- Objetivo: ${objetivo}
- Dias sem interação: ${dias}
- Último treino: ${ultimoTreino}
- Treinos no mês: ${treinosMes}
- Tom desejado: ${tom}

REGRAS:
- Máximo 4 linhas
- Use 1-2 emojis
- Inclua uma pepita de sabedoria sobre disciplina/saúde
- Termine com um CTA claro: sugira /peso, /treino ou /progresso
- Português do Brasil
- NUNCA julgue ou critique a ausência`;

return {
  ...user,
  prompt_nudge: prompt,
  tom: tom
};

const u = $json;
const nome = u.nome || 'amigo(a)';
const objetivo = u.objetivo || 'manter forma';
const treinos = u.treinos_semana || 0;
const minutos = u.minutos_semana || 0;
const grupoTop = u.grupo_top || 'variado';
const meta = u.frequencia_treino_estimada || 0;
const pesoInicio = u.peso_inicio_semana;
const pesoFim = u.peso_fim_semana;
const totalHistorico = u.total_treinos_historico || 0;

// Calcula variação de peso
let pesoDiff = '';
if (pesoInicio && pesoFim) {
  const diff = (pesoFim - pesoInicio).toFixed(1);
  const sinal = diff >= 0 ? '+' : '';
  pesoDiff = `Peso: ${pesoInicio}kg → ${pesoFim}kg (${sinal}${diff}kg)`;
} else {
  pesoDiff = 'Sem registros de peso essa semana';
}

// Calcula atingimento da meta
let metaMsg = '';
if (meta > 0) {
  const pct = Math.round((treinos / meta) * 100);
  metaMsg = `Meta semanal: ${treinos}/${meta} treinos (${pct}%)`;
}

// Detecta streak
let streakMsg = '';
if (treinos >= meta && meta > 0) {
  streakMsg = 'Meta atingida! 🎯';
} else if (treinos >= 3) {
  streakMsg = 'Semana produtiva!';
}

const prompt = `Gere um relatório semanal motivacional para:
- Nome: ${nome}
- Objetivo: ${objetivo}
- Treinos na semana: ${treinos} (${minutos} minutos total)
- ${metaMsg}
- Grupo mais treinado: ${grupoTop}
- ${pesoDiff}
- Total treinos no histórico: ${totalHistorico}
- ${streakMsg}

REGRAS:
- Máximo 8 linhas
- Comece com "📊 Resumo semanal, ${nome}!"
- Use emojis com moderação (3-5)
- Destaque conquistas primeiro
- Sugira melhoria gentilmente
- Inclua um ensinamento sobre consistência
- Termine com: "Boa semana! Use /treino para um novo treino ou /progresso para ver gráficos"
- Português do Brasil`;

return {
  ...u,
  prompt_semanal: prompt
};

